const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9]\d*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(line, message) {
  throw new ParseError(message, line)
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null // array of names, in declared order
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue

    const tokens = raw.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        fail(lineNo, 'expected candidates <name>...')
      }
      const names = tokens.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(lineNo, `invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNo, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      candidateSet.clear()
      for (const name of names) candidateSet.add(name)
      continue
    }

    if (word === 'ballot') {
      if (candidates === null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        fail(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        fail(lineNo, 'count must be a positive integer')
      }
      const count = Number(countToken)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, prefs: names })
      continue
    }

    fail(lineNo, `unknown directive ${word}`)
  }

  if (candidates === null) {
    fail(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

