{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-NYXD3W/src/count.js","content":"/**
 * Runs the instant-runoff count for a parsed election.
 * Returns { rounds, winner } where rounds is an array of
 * { counts: [{ name, votes }], exhausted, eliminated } in the order counted,
 * counts sorted by descending votes then ascending name, and
 * winner is the winning candidate's name or null.
 */

export function runElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const roundHistory = [] // array of Map(name -> votes), one per round counted
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const pick = ballot.prefs.find((name) => continuing.has(name))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(pick, votes.get(pick) + ballot.count)
      }
    }

    roundHistory.push(votes)

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    const counts = [...votes.entries()]
      .map(([name, v]) => ({ name, votes: v }))
      .sort((a, b) => (b.votes - a.votes) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

    let roundWinner = null
    if (activeTotal > 0) {
      for (const { name, votes: v } of counts) {
        if (v * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    if (roundWinner !== null) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = null
      break
    }

    // Eliminate exactly one candidate.
    const minVotes = Math.min(...continuing.values ? [...continuing].map((n) => votes.get(n)) : [])
    let tied = [...continuing].filter((n) => votes.get(n) === minVotes)

    if (tied.length > 1) {
      for (const roundVotes of roundHistory) {
        const values = tied.map((n) => roundVotes.get(n))
        const min = Math.min(...values)
        const next = tied.filter((n) => roundVotes.get(n) === min)
        if (next.length < tied.length) {
          tied = next
        }
        if (tied.length === 1) break
      }
    }

    let eliminated
    if (tied.length === 1) {
      eliminated = tied[0]
    } else {
      eliminated = tied.reduce((a, b) => (a > b ? a : b))
    }

    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

