function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }

  let text
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }

  let election
  try {
    election = parseElection(text)
  } catch (e) {
    if (e instanceof ParseError) {
      if (e.line === null || e.line === undefined) {
        fail(e.message)
      } else {
        fail(`line ${e.line}: ${e.message}`)
      }
      return
    }
    throw e
  }

  const { rounds, winner } = runElection(election)

  const out = []
  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      const round = rounds[i]
      const parts = round.counts.map(({ name, votes }) => `${name}=${votes}`)
      parts.push(`exhausted=${round.exhausted}`)
      out.push(`round ${i + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    }
  } else {
    out.push(`rounds ${rounds.length}`)
  }

  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

main()
